/* Peck Deck service worker — FLEDGE Phase 7.
 *
 * Hand-written rather than generated by a build plugin, because the app needs
 * exactly three behaviours and each one wants a different strategy:
 *
 *   1. App shell        — network-first, cache fallback. Opens offline.
 *   2. Hashed assets    — cache-first. Filenames are content-addressed, so a
 *                         cached entry can never be stale.
 *   3. API reads        — network-first, cache fallback, so a flaky connection
 *                         shows the last-known feed instead of an error page.
 *
 * It also receives web push (RFC 8291, decrypted by the browser before it gets
 * here) and turns it into a notification.
 *
 * Bump VERSION to invalidate every cache. Registration lives in
 * src/registerSW.js and only runs in production builds — a service worker in
 * front of the Vite dev server would serve stale modules and fight HMR.
 */
const VERSION = "v1";
const SHELL_CACHE = `peckdeck-shell-${VERSION}`;
const ASSET_CACHE = `peckdeck-assets-${VERSION}`;
const API_CACHE = `peckdeck-api-${VERSION}`;
const CURRENT_CACHES = [SHELL_CACHE, ASSET_CACHE, API_CACHE];

// Enough to paint the app offline. Everything else arrives through the runtime
// caches on first online visit; listing hashed bundle names here is impossible
// without a build step reading the manifest.
const SHELL_URLS = [
  "/",
  "/index.html",
  "/manifest.webmanifest",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/apple-touch-icon-180.png",
];

// API reads worth keeping for an offline open. Anything not matched here (login,
// writes, the CSV/JSON export) goes straight to the network every time.
const CACHEABLE_API = /^\/api\/(meta|species|sightings|devices|users|stats)/;

const OFFLINE_BODY = JSON.stringify({
  status_code: 503,
  type: "ServiceUnavailable",
  detail: "You're offline and this hasn't been loaded before.",
  offline: true,
});

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(SHELL_CACHE).then((cache) =>
      // addAll is atomic: one 404 would fail the whole install and leave the
      // previous worker in place, so shell URLs are added individually.
      Promise.all(
        SHELL_URLS.map((url) => cache.add(new Request(url, { cache: "reload" })).catch(() => {}))
      )
    )
  );
  // No skipWaiting: a new worker takes over on the next visit instead of
  // swapping caches out from under a page that is still running.
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((k) => k.startsWith("peckdeck-") && !CURRENT_CACHES.includes(k))
            .map((k) => caches.delete(k))
        )
      )
      .then(() => self.clients.claim())
  );
});

self.addEventListener("message", (event) => {
  // Lets the page opt into an immediate update ("Reload to update").
  if (event.data === "SKIP_WAITING") self.skipWaiting();
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return; // never cache a write

  const url = new URL(request.url);

  if (request.mode === "navigate") {
    event.respondWith(networkFirst(request, SHELL_CACHE, "/index.html"));
    return;
  }

  if (url.origin !== self.location.origin) return; // fonts etc. — leave alone

  if (url.pathname.startsWith("/api/")) {
    if (CACHEABLE_API.test(url.pathname) && !url.pathname.includes("/export")) {
      event.respondWith(networkFirst(request, API_CACHE));
    }
    return;
  }

  if (url.pathname.startsWith("/assets/") || url.pathname.startsWith("/icons/")) {
    event.respondWith(cacheFirst(request, ASSET_CACHE));
  }
});

/** Cache-first — for content-addressed files that cannot go stale. */
async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);
  if (hit) return hit;
  const response = await fetch(request);
  if (isCacheable(response)) cache.put(request, response.clone());
  return response;
}

/**
 * Network-first — fresh when online, last-known when not.
 *
 * `fallbackUrl` covers navigations: any in-scope URL falls back to the cached
 * shell, since the app routes client-side and index.html can answer for all of
 * them.
 */
async function networkFirst(request, cacheName, fallbackUrl) {
  const cache = await caches.open(cacheName);
  try {
    const response = await fetch(request);
    if (isCacheable(response)) cache.put(request, response.clone());
    return response;
  } catch (err) {
    const hit = (await cache.match(request)) || (fallbackUrl && (await cache.match(fallbackUrl)));
    if (hit) return hit;
    if (fallbackUrl) throw err; // nothing sensible to render
    return new Response(OFFLINE_BODY, {
      status: 503,
      headers: { "Content-Type": "application/json" },
    });
  }
}

function isCacheable(response) {
  // Opaque (cross-origin no-cors) responses can't be inspected and cache.put
  // rejects them; a 401 must never be stored or it would outlive the session.
  return response && response.status === 200 && response.type !== "opaque";
}

// ── Web push ────────────────────────────────────────────────────────────────
self.addEventListener("push", (event) => {
  // A push that shows nothing is treated as abuse by browsers (and can cost the
  // app its permission), so every branch ends in showNotification.
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    payload = { body: event.data ? event.data.text() : "" };
  }

  const title = payload.title || "Peck Deck";
  event.waitUntil(
    self.registration.showNotification(title, {
      body: payload.body || "A bird visited your feeder.",
      icon: "/icons/icon-192.png",
      badge: "/icons/icon-192.png",
      // Collapses a backlog of alerts from one feeder into the latest.
      tag: payload.tag || "peckdeck",
      renotify: true,
      data: payload.data || {},
    })
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = new URL(event.notification.data?.url || "/", self.location.origin).href;

  event.waitUntil(
    (async () => {
      const clientList = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });
      // Prefer an open tab — focusing beats opening a second copy of the app.
      for (const client of clientList) {
        if (client.url.startsWith(self.location.origin) && "focus" in client) {
          await client.focus();
          if ("navigate" in client && client.url !== target) await client.navigate(target);
          return;
        }
      }
      await self.clients.openWindow(target);
    })()
  );
});
